.esstic-transcript{box-sizing:border-box;min-height:{{ $page_size==='a3'?382:260 }}mm;display:flex;flex-direction:column;font-family:'Times New Roman',serif;font-size:{{ $page_size==='a3'?10:7 }}px;line-height:1.1;padding:2mm 1mm}
.esstic-official{display:flex;justify-content:space-between;text-align:center;font-size:{{ $page_size==='a3'?11:8 }}px;line-height:1.15}.esstic-official>div{width:35%}.esstic-official strong{font-size:110%}
.esstic-brand{display:grid;grid-template-columns:19% 62% 19%;align-items:center;text-align:center;margin:3mm 0 2mm;font-family:Arial,sans-serif;font-size:{{ $page_size==='a3'?10:7 }}px;font-weight:bold}.esstic-brand strong{display:block;font-size:{{ $page_size==='a3'?21:15 }}px;margin-bottom:2mm}.esstic-brand img{display:block;max-width:{{ $page_size==='a3'?28:20 }}mm;max-height:{{ $page_size==='a3'?28:20 }}mm;object-fit:contain;margin:auto}
.esstic-rule{border-top:2px solid #d3232b;border-bottom:1px solid #d3232b;height:2px;margin:3mm 0 2mm}.esstic-transcript h1{text-align:center;font-size:{{ $page_size==='a3'?12:8 }}px;margin:0 0 2mm;color:#111}.esstic-identity{display:grid;grid-template-columns:1fr 1fr;gap:5mm;font-size:{{ $page_size==='a3'?10:7 }}px;line-height:1.5;margin-bottom:2mm}
.esstic-transcript table{border-collapse:collapse;width:100%;table-layout:fixed;margin:0;font-size:{{ $page_size==='a3'?9:6 }}px}.esstic-transcript td,.esstic-transcript th{border:1px solid #222;padding:1px 2px;line-height:1.06;background:#fff;vertical-align:middle}.esstic-transcript .left{text-align:left}.esstic-marks th{font-weight:bold}.esstic-module td,.esstic-module th{font-weight:bold;background:#f1f1f1}.esstic-ue{width:8%}.esstic-code{width:8%}.esstic-course{width:28%}.esstic-mark{width:8%}.esstic-mgp{width:7%}.esstic-credit,.esstic-earned{width:8%}.esstic-semester{width:7%}.esstic-year{width:11%}.esstic-mention{width:7%}
.esstic-bilan{margin-top:3mm!important}.esstic-bilan th{text-align:left}.esstic-issued{text-align:center;margin:4mm 0 2mm;font-weight:bold}.esstic-signatures{display:flex;justify-content:space-between;margin:0 3mm;min-height:{{ $page_size==='a3'?29:20 }}mm;font-weight:bold}.esstic-note{margin-top:auto;text-align:center;border-top:3px solid #ee111b;color:#333;font-size:{{ $page_size==='a3'?9:6 }}px;padding-top:1mm}
@media print{.modele-esstic.document-releve .preview{display:none}.esstic-transcript{min-height:{{ $page_size==='a3'?376:260 }}mm;break-after:page;page-break-after:always}.esstic-transcript:last-of-type{break-after:auto;page-break-after:auto}.esstic-marks tr{break-inside:avoid}}
